changeSet.sql:
DROP SCHEMA IF EXISTS dm_ownerread CASCADE;
CREATE SCHEMA dm_ownerread;

DO $$
DECLARE
    t     text;
    own   text := CASE WHEN EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nexus_admin_dmlutils')
                       THEN 'nexus_admin_dmlutils' ELSE 'nexus_svc' END;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dm_ownerread_login') THEN
        CREATE ROLE dm_ownerread_login LOGIN PASSWORD 'dm_ownerread_login_pw' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
    END IF;
    FOREACH t IN ARRAY ARRAY['rows', 'other'] LOOP
        EXECUTE format('CREATE TABLE dm_ownerread.%I (tenant_id text NOT NULL, id bigint NOT NULL, payload text, n integer NOT NULL DEFAULT 0, touched_by text, PRIMARY KEY (tenant_id, id))', t);
        EXECUTE format('ALTER TABLE dm_ownerread.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE dm_ownerread.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY tenant_isolation ON dm_ownerread.%I USING (tenant_id = current_setting(%L, true)) WITH CHECK (tenant_id = current_setting(%L, true))',
                       t, 'nexus.tenant', 'nexus.tenant');
        EXECUTE format('INSERT INTO dm_ownerread.%I (tenant_id, id, payload) SELECT x, g, ''p'' || g FROM unnest(ARRAY[''default'', ''acme'', ''globex'']) x, generate_series(1, 100) g', t);
        EXECUTE format('ALTER TABLE dm_ownerread.%I OWNER TO %I', t, own);
        EXECUTE format('GRANT SELECT, UPDATE ON dm_ownerread.%I TO nexus_svc', t);
    END LOOP;
    EXECUTE format('ALTER SCHEMA dm_ownerread OWNER TO %I', own);
END $$;
GRANT USAGE ON SCHEMA dm_ownerread TO nexus_svc;
